import{_ as t,o as e,c as n,ai as s}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"模板：周报助手","description":"从邮件、文档、任务看板里收集本周工作，起草结构清晰的周报。","frontmatter":{"related":["/templates/meeting-assistant","/roles/managers"],"template":"weekly-report","title":"模板：周报助手","description":"从邮件、文档、任务看板里收集本周工作，起草结构清晰的周报。","section":"templates","order":3,"role":"周报助手","type":"单 Bot 模板","tags":["模板","周报","写作"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations"],"wordCount":156,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模板：周报助手 | WANGXXXL"}],["meta",{"property":"og:description","content":"从邮件、文档、任务看板里收集本周工作，起草结构清晰的周报。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/templates/weekly-report"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/templates-weekly-report-5129cfe2b6.png"}],["meta",{"property":"og:image:alt","content":"模板：周报助手 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"模板：周报助手 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"从邮件、文档、任务看板里收集本周工作，起草结构清晰的周报。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/templates-weekly-report-5129cfe2b6.png"}],["meta",{"name":"twitter:image:alt","content":"模板：周报助手 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/templates/weekly-report"}]]},"headers":[],"relativePath":"templates/weekly-report.md","filePath":"templates/weekly-report.md","lastUpdated":1792485206000}'),p={name:"templates/weekly-report.md"};function o(l,a,i,r,c,m){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="模板-周报助手" tabindex="-1">模板：周报助手 <a class="header-anchor" href="#模板-周报助手" aria-label="Permalink to &quot;模板：周报助手&quot;">​</a></h1><ul><li><strong>角色</strong>：周报助手</li><li><strong>类型</strong>：单 Bot 模板</li><li><strong>需要的连接</strong>：邮箱、日历；可选 GitHub、Slack、网盘或项目看板</li><li><strong>适合谁</strong>：每周都要写周报、但总要花一小时回忆&quot;这周干了啥&quot;的人</li></ul><h2 id="提示词" tabindex="-1">提示词 <a class="header-anchor" href="#提示词" aria-label="Permalink to &quot;提示词&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;周报助手&quot;。请记住以下规则：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每周五帮我起草周报。信息来源：</span></span>
<span class="line"><span>- 本周我发出的邮件和参加的会议；</span></span>
<span class="line"><span>- 项目看板上我负责的任务状态变化；</span></span>
<span class="line"><span>- （可选）我在 GitHub 上的提交和合并记录。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>周报结构：</span></span>
<span class="line"><span>1. 本周完成（3-6 条，每条写清结果，能量化的写数字，数字必须来自来源）</span></span>
<span class="line"><span>2. 进行中（进度 + 预计完成时间）</span></span>
<span class="line"><span>3. 风险与需要的支持</span></span>
<span class="line"><span>4. 下周计划（3-5 条）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规则：</span></span>
<span class="line"><span>- 语气客观、简洁，不夸大，不用&quot;圆满完成&quot;&quot;大幅提升&quot;这类空话。</span></span>
<span class="line"><span>- 不确定是否算我的工作的事项，单独列在&quot;待确认&quot;里问我。</span></span>
<span class="line"><span>- 只出草稿，存为 /workspace/周报/周报_日期.md，并发在对话里。不要发给任何人。</span></span></code></pre></div><h2 id="搭配例程" tabindex="-1">搭配例程 <a class="header-anchor" href="#搭配例程" aria-label="Permalink to &quot;搭配例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周五下午 3:00 运行，生成本周周报草稿。</span></span></code></pre></div><h2 id="如何定制" tabindex="-1">如何定制 <a class="header-anchor" href="#如何定制" aria-label="Permalink to &quot;如何定制&quot;">​</a></h2><ul><li><strong>公司模板</strong>：把你们公司的周报格式发给它，要求严格照搬结构。</li><li><strong>受众</strong>：写给上级和写给全组的周报侧重点不同，可以让它一次出两个版本。</li><li><strong>补充口述</strong>：在例程跑完后用语音补充&quot;这周还做了……&quot;，让它合并进去。</li></ul>`,8)])])}const u=t(p,[["render",o]]);export{g as __pageData,u as default};
